import{_ as a,o as t,c as s,a2 as i}from"./chunks/framework.BvlN9b-o.js";const k=JSON.parse('{"title":"跟做：上传附件、引用图片与下载","description":"","frontmatter":{},"headers":[],"relativePath":"tutorials/attachments.md","filePath":"tutorials/attachments.md"}'),n={name:"tutorials/attachments.md"};function r(o,e,l,p,c,d){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="跟做-上传附件、引用图片与下载" tabindex="-1">跟做：上传附件、引用图片与下载 <a class="header-anchor" href="#跟做-上传附件、引用图片与下载" aria-label="Permalink to &quot;跟做：上传附件、引用图片与下载&quot;">​</a></h1><p><code>just dev</code> 现在启动 PostgreSQL 与 RustFS，运行数据库迁移，并初始化专用私有 bucket 的浏览器 CORS。首次运行需要拉取固定版本镜像；API/Web 仍支持原来的开发反馈循环。</p><p>保存一篇文档，在“附件”选择文件并点击“上传附件”。页面显示准备、上传进度和校验状态，校验完成后附件才进入列表。点击下载可以取回原始字节；图片可以在编辑页点击“插入引用”，切到预览查看，再显式保存正文。</p><p>默认单文件上限 20 MiB、上传会话 15 分钟、下载链接 60 秒。实际值来自<a href="./../reference/config">生成配置参考</a>，不能只修改前端提示。</p><h2 id="_1-浏览器拿到的是受限能力" tabindex="-1">1. 浏览器拿到的是受限能力 <a class="header-anchor" href="#_1-浏览器拿到的是受限能力" aria-label="Permalink to &quot;1. 浏览器拿到的是受限能力&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/7f59fcc56834d3fcb28fd273e5a8e97a1ceaf90e/apps/web/src/knowledge-files.ts" target="_blank" rel="noreferrer">Web 文件适配</a>负责读取 File、计算 SHA-256、XHR 上传进度和实际下载。应用 Cookie 只用于自己的 API，对 S3 传输省略凭据。单次字节传输最多 120 秒（包含响应体读取），超时后恢复重试操作；离开页面会取消传输。</p><p>申请上传时发送文件名、MIME、大小和校验和。服务端验证文档编辑权，生成暂存 key，保存上传记录及业务关联，并返回 URL、方法、必需 headers 与截止时间。前端不能指定 bucket/key，也拿不到存储管理密钥。原始文件名只是显示值，不用作对象路径。</p><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/7f59fcc56834d3fcb28fd273e5a8e97a1ceaf90e/crates/platform/src/object_storage.rs" target="_blank" rel="noreferrer">ObjectStorage 适配器</a>使用标准 S3 API，固定 RustFS 1.0.0 与 AWS SDK 1.149.0。内部操作端点与公开签名端点分开，先按公开地址签名，不事后改 hostname 或路径。签名绑定类型、校验头与上传标识；Content-Encoding 固定为 identity，避免下载时发生内容解码变化。浏览器控制的 Content-Length 不进入返回 headers。</p><p>专用 bucket 默认私有。初始化只在 HEAD 确认 404 时创建，不把 403 当作不存在；可重复执行的初始化使用有上限的标准重试，覆盖实测的并发 CreateBucket <code>503 SlowDown</code>。条件复制保持一次尝试，超时结果通过候选记录处理。</p><h2 id="_2-上传到存储-不代表附件已经发布" tabindex="-1">2. 上传到存储，不代表附件已经发布 <a class="header-anchor" href="#_2-上传到存储-不代表附件已经发布" aria-label="Permalink to &quot;2. 上传到存储，不代表附件已经发布&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/7f59fcc56834d3fcb28fd273e5a8e97a1ceaf90e/crates/app/src/modules/files/mod.rs" target="_blank" rel="noreferrer">Core Files</a>拥有文件状态和候选对象记录；<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/7f59fcc56834d3fcb28fd273e5a8e97a1ceaf90e/crates/app/src/modules/knowledge/attachments.rs" target="_blank" rel="noreferrer">知识库附件用例</a>拥有文档关联和库级授权。Core 不读取 Document 或 Grant 表。</p><p>完成操作分三个阶段：</p><ol><li>短事务重新验证文档编辑权，先登记唯一候选 key，再提交。</li><li>在事务外读取暂存对象 ETag，条件复制到独占候选 key，检查候选的实际长度、MIME/上传标识、完整字节和 SHA-256。</li><li>再次验证当前凭据、文档存在性、Grant、上传状态与期限，原子选定唯一 ready 对象、关联附件并写入 Audit。</li></ol><p>候选复制同时使用源 ETag 条件和目标 <code>If-None-Match: *</code>。发布后不再写这个 key；旧上传 URL 只能作用于暂存对象。两个完成请求竞争时，只有一个候选被采用，其他请求返回同一附件。</p><p>图片与 PDF 额外检查文件标识；其他类型按声明的 MIME 和完整字节校验下载。本模板不做通用文档解析或恶意内容扫描，上传 HTML 也不会被当作可信应用页面执行。</p><h2 id="_3-重试与失败" tabindex="-1">3. 重试与失败 <a class="header-anchor" href="#_3-重试与失败" aria-label="Permalink to &quot;3. 重试与失败&quot;">​</a></h2><p>创建上传资源使用 Idempotency-Key，记录稳定 upload_id。短期 URL 每次重新授权后生成，截止时间不超过上传会话。网络失败可重试同一资源；过期或被拒绝时明确提示重新上传，并使用新资源。</p><p>大小/类型不匹配不会发布；撤权、认证会话过期或源文档消失也会阻止最终提交。审计失败时 ready 状态与附件关联一起回滚，之后仍可重试完成。</p><p>每个候选在 I/O 前就有持久记录。复制超时可能已经在远端成功，失败候选和暂存位置不会被遗忘；后续清理章节会处理过期、拒绝与删除对象。不能把一次 Delete 或 SDK timeout 当作“再也不会出现晚到对象”的证明。</p><h2 id="_4-短期下载与-markdown-引用" tabindex="-1">4. 短期下载与 Markdown 引用 <a class="header-anchor" href="#_4-短期下载与-markdown-引用" aria-label="Permalink to &quot;4. 短期下载与 Markdown 引用&quot;">​</a></h2><p>只有仍关联可见文档的 ready 附件可以取得新下载链接。Reader 可下载，Editor 可上传；撤权后不能继续申请链接，已经签发的链接在到期前仍可能有效，已接受的传输也可能继续。这是此直下载模式的明确权限边界。</p><p>默认下载使用 attachment disposition、no-store 和安全文件名编码。Web 将下载内容校对长度后保存为二进制文件；临时 Blob URL 随后释放。</p><p>Markdown 保存的是 <code>attachment:&lt;附件 ID&gt;</code>，不会保存预签名 URL 或永久公开地址。<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/7f59fcc56834d3fcb28fd273e5a8e97a1ceaf90e/packages/views/src/knowledge/attachment-markdown.tsx" target="_blank" rel="noreferrer">Markdown 附件渲染</a>验证引用格式，再按当前文档与成员向 API 请求访问能力。只有通过检查的常见位图支持 inline 预览；其他附件用下载动作，任意外链图片仍不会自动加载。</p><h2 id="_5-从本地配置到自己的部署" tabindex="-1">5. 从本地配置到自己的部署 <a class="header-anchor" href="#_5-从本地配置到自己的部署" aria-label="Permalink to &quot;5. 从本地配置到自己的部署&quot;">​</a></h2><p>本地 <code>.env.example</code> 提供仅用于开发的 RustFS 凭据。关键配置为：</p><ul><li><code>S3_ENDPOINT</code>：API/Worker 使用的内部 S3 根地址；不设置时文件能力关闭，文本与认证继续工作。</li><li><code>S3_PUBLIC_ENDPOINT</code>：浏览器可访问的独立 S3 origin；生产使用 HTTPS，不挂在会改写路径的子目录。</li><li><code>S3_BUCKET / S3_REGION / S3_ACCESS_KEY / S3_SECRET_KEY</code>：专用 bucket 与显式服务端凭据。</li><li><code>FILE_MAX_BYTES / UPLOAD_SESSION_SECS / DOWNLOAD_URL_SECS</code>：实际上传与签名边界。</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bootstrap-storage</span></span></code></pre></div><p>初始化命令像 <code>just dev</code> 一样加载 <code>.env.example</code> / <code>.env</code> 及进程环境，使用应用配置管理专用 bucket 的 CORS。RustFS 数据和日志命名卷需允许 UID/GID 10001 写入；<code>/health/ready</code> 用于就绪判断。<code>Ctrl+C</code> 停止 API/Web，数据卷保留。</p><h2 id="_6-验证同一条路径" tabindex="-1">6. 验证同一条路径 <a class="header-anchor" href="#_6-验证同一条路径" aria-label="Permalink to &quot;6. 验证同一条路径&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/test-storage.mjs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/test-backend.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> attachments</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vitest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/web/src/attachments.test.tsx</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span></code></pre></div><p>存储测试连接真实 RustFS，覆盖期限与签名头、错误校验和、字节读取、源/目标复制条件与并发初始化。HTTP 测试连接真实数据库和存储，覆盖暂存不可见、唯一发布、重放、期限、大小/类型、审计回滚、Reader/Editor、跨文档引用，以及复制期间撤权/会话过期/源资源消失。</p><p>View 测试使用真实页面、WebCrypto 和 HTTP 边界，验证上传进度、失败后复用资源、大小限制、只读、引用插入和安全图片 URL。关键旅程完成后运行一次：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/e2e.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/e2e/attachments.spec.ts</span></span></code></pre></div><p>浏览器上传真实图片，下载后比对字节，再保存附件引用并刷新预览。默认反馈循环不重复运行浏览器旅程。</p><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/7f59fcc56834d3fcb28fd273e5a8e97a1ceaf90e/examples/knowledge-base/manifest.json" target="_blank" rel="noreferrer">所有权清单</a>将附件关联、业务路由、Views、Web 接线与教程归到知识库示例；Core Files、S3 adapter、通用配置与隔离测试运行器会保留，供自己的业务复用。</p><hr><p>源码版本：<code>7f59fcc56834</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/7f59fcc56834d3fcb28fd273e5a8e97a1ceaf90e/docs/tutorials/09-attachments.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>`,37)])])}const b=a(n,[["render",r]]);export{k as __pageData,b as default};
